def transform(grid):
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v]
    colors = sorted({v for _, _, v in cells})
    period = len(colors)
    mappings = []
    for key in (lambda r, c: r + c, lambda r, c: r - c):
        lines = {}
        valid = True
        for r, c, v in cells:
            d = key(r, c)
            if v in lines and lines[v] != d:
                valid = False
                break
            lines[v] = d
        if valid:
            residues = {d % period: v for v, d in lines.items()}
            if len(residues) == period:
                mappings.append(residues)
    if not mappings:
        raise ValueError('Could not infer diagonal pattern')
    # These tasks encode a color cycle on parallel diagonals; use the valid orientation.
    residues = mappings[0]
    h, w = len(grid), len(grid[0])
    # Select matching orientation (sum first, difference second) by which lines are aligned.
    # The first mapping is valid when the sum-diagonal encoding applies.
    key = (lambda r, c: r + c) if len(mappings) == 1 and all(len({r+c for r,c,v in cells if v==col}) == 1 for col in colors) else (lambda r, c: r - c)
    return [[residues[key(r, c) % period] for c in range(w)] for r in range(h)]

